CREATE TABLE "delivery_policy_revisions" (
	"id" integer PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY (sequence name "delivery_policy_revisions_id_seq" INCREMENT BY 1 MINVALUE 1 MAXVALUE 2147483647 START WITH 1 CACHE 1),
	"version" integer NOT NULL,
	"pickup_enabled" boolean NOT NULL,
	"delivery_enabled" boolean NOT NULL,
	"flat_fee" numeric(12, 2) NOT NULL,
	"minimum_products_total" numeric(12, 2),
	"free_shipping_from" numeric(12, 2),
	"is_demo" boolean DEFAULT true NOT NULL,
	"created_by" integer NOT NULL,
	"created_at" timestamp DEFAULT now() NOT NULL,
	CONSTRAINT "delivery_policy_revisions_version_unique" UNIQUE("version"),
	CONSTRAINT "delivery_policy_amounts_check" CHECK ("delivery_policy_revisions"."version" > 0 and "delivery_policy_revisions"."flat_fee" >= 0 and "delivery_policy_revisions"."flat_fee" = trunc("delivery_policy_revisions"."flat_fee") and ("delivery_policy_revisions"."minimum_products_total" is null or ("delivery_policy_revisions"."minimum_products_total" >= 0 and "delivery_policy_revisions"."minimum_products_total" = trunc("delivery_policy_revisions"."minimum_products_total"))) and ("delivery_policy_revisions"."free_shipping_from" is null or ("delivery_policy_revisions"."free_shipping_from" > 0 and "delivery_policy_revisions"."free_shipping_from" = trunc("delivery_policy_revisions"."free_shipping_from"))))
);
