CREATE FUNCTION fyf_immutable_delivery_revision() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  RAISE EXCEPTION 'Las revisiones de despacho son inmutables' USING ERRCODE = '23514';
END;
$$;
--> statement-breakpoint
CREATE TRIGGER delivery_revision_immutable BEFORE UPDATE OR DELETE ON delivery_policy_revisions
FOR EACH ROW EXECUTE FUNCTION fyf_immutable_delivery_revision();
--> statement-breakpoint
CREATE FUNCTION fyf_preserve_order_amounts() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF (NEW.total, NEW.products_subtotal, NEW.products_discount_total, NEW.delivery_fee, NEW.delivery_policy_revision_id, NEW.delivery_fee_reason, NEW.delivery_type)
    IS DISTINCT FROM
    (OLD.total, OLD.products_subtotal, OLD.products_discount_total, OLD.delivery_fee, OLD.delivery_policy_revision_id, OLD.delivery_fee_reason, OLD.delivery_type) THEN
    RAISE EXCEPTION 'Los importes y la modalidad del pedido son historicos e inmutables' USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$$;
--> statement-breakpoint
CREATE TRIGGER online_order_amounts_immutable BEFORE UPDATE ON online_orders
FOR EACH ROW EXECUTE FUNCTION fyf_preserve_order_amounts();
